 IEnumerator Start(){folder=Path.GetFullPath("Logs/TruckSports/EssentialRelease/SkyTow/"+(Application.isEditor?"Native/":"Windows/")+mode);Directory.CreateDirectory(folder);File.WriteAllText(folder+"/result.txt","RUNNING "+DateTime.UtcNow.ToString("o"));Application.logMessageReceived+=Error;yield return SportsProbeScene.Ensure<SkyTowMatch>("TruckSkyTow");yield return null;var m=FindAnyObjectByType<SkyTowMatch>();Check(m!=null&&m.course.route.Spline.Count>=14&&m.course.rings.Length==144&&m.racers.Length==4,"saved scene has the authored six-section spline,144 swept whole-truck course gates and four physical tows");foreach(var entry in m.presets.entries)if(entry.displayName=="Clear"){m.presets.Select(entry.id);break;}m.setup.count=4;m.NormalizeSetup();m.AllBots();for(int i=0;i<4;i++)m.setup.players[i].difficulty=mode=="easy"?BowlingDifficulty.Easy:mode=="hard"?BowlingDifficulty.Hard:BowlingDifficulty.Normal;if(mode=="flight"){foreach(var ring in m.course.rings){var collider=ring.GetComponent<Collider>();if(collider!=null)collider.enabled=false;}report.AppendLine("DIAGNOSTIC: hoop contacts disabled; real PhysX tether, terrain, wind, AI inputs and swept score gates remain active.");}var scoreTally=new SportsScoreAcceptance.Tally(m);bool awardCaptured=false;Check(m.StartMatch(),"four physical AI tows start without controllers");Time.timeScale=4;float end=Time.realtimeSinceStartup+120,next=0;bool paused=false,captured=false;var airborne=new float[4];while(!m.Finished&&Time.realtimeSinceStartup<end){if(!awardCaptured&&m.ScoreJournal.Count>0){awardCaptured=true;yield return SportsScoreAcceptance.CaptureAward(m,Check,folder+"/confirmed-score");}if(m.Phase==SkyTowPhase.Run){for(int i=0;i<4;i++)if(!m.racers[i].Failed&&m.racers[i].truck.body.position.y>.8f)airborne[i]+=Time.deltaTime;}if(!paused&&m.Age>35){paused=true;var position=m.racers[0].truck.body.position;float age=m.Age;m.Pause();yield return new WaitForSecondsRealtime(.25f);Check(position==m.racers[0].truck.body.position&&m.Age==age,"pause preserves actual flight and spline progress");m.Resume();Time.timeScale=4;}if(!captured&&m.Age>20){captured=true;foreach(var size in new[]{new Vector2Int(1280,720),new Vector2Int(1920,1080),new Vector2Int(1440,1080),new Vector2Int(2560,1080)}){SportsControlledCapture.Save(m,size.x,size.y,folder+"/tow-"+size.x+"x"+size.y+".png");yield return null;}}if(Time.realtimeSinceStartup>=next){next=Time.realtimeSinceStartup+2;report.AppendLine("LIVE "+m.Phase+" age="+m.Age.ToString("F2")+" wind="+m.atmosphere.Flow+" physicalRings="+m.PhysicalRings);for(int i=0;i<4;i++)report.AppendLine("TRUCK "+i+" p="+m.racers[i].truck.body.position+" v="+m.racers[i].truck.body.linearVelocity+" cable="+m.racers[i].FurthestCable+" air="+m.racers[i].LastAirspeed+" lift="+m.racers[i].LastLift+" input="+m.racers[i].LastControl+" failed="+m.racers[i].Failed+" hits="+m.rules.hits[i]);Write();}yield return null;}
 scoreTally.Verify(slot=>m.rules.score[slot],Check);scoreTally.Dispose();if(m.Finished)yield return SportsResultsAcceptance.Capture(m,Check,folder,m.ResultPlace,slot=>(double?)m.rules.score[slot],slot=>m.rules.winners[slot]);
 Check(m.Finished&&m.rules.Complete,"actual flight resolves a complete four-participant match");Check(m.Age>=110&&m.Age<=130,"uninterrupted full course takes110–130 simulated seconds");Check(m.PhysicalRings>=32,"AI earns meaningful scores from actual swept ring passages");for(int i=0;i<4;i++){Check(!m.racers[i].Failed&&airborne[i]>110,"truck "+i+" completes the route airborne on its real tether");Check(m.racers[i].FurthestCable<40,"truck "+i+" tow length remains bounded");int resolved=0;for(int r=0;r<36;r++)if(m.rules.outcomes[i,r]!=0)resolved++;Check(resolved==36,"truck "+i+" resolves every ring once");report.AppendLine("FINAL "+i+" score="+m.rules.score[i]+" rings="+m.rules.hits[i]+" airborne="+airborne[i]+" winner="+m.rules.winners[i]);}int earned=m.rules.score[0];var endPosition=m.racers[0].truck.body.position;Check(m.review!=null&&m.review.Play(),"completed flight offers the actual recorded replay");yield return new WaitForSecondsRealtime(.4f);Check(m.rules.score[0]==earned&&m.racers[0].truck.body.position==endPosition,"replay cannot alter the physical result or earned scores");m.ExtraAction("replayangle");m.ExtraAction("replayspeed");Check(m.review.motion.Angle==1&&m.review.motion.Speed<1,"replay supports alternate camera and slow motion");m.ExtraAction("replayrewind");m.ExtraAction("replayskip");Check(!m.review.Active&&m.menus.Screen==SportsEventScreen.Result,"replay skip returns to locked results");m.SetupScreen();Check(m.StartMatch()&&m.Age==0&&m.rules.score[0]==0&&!m.racers[0].Failed,"rematch clears ring outcomes, scores, flight and cable state");yield return null;m.SetupScreen();SportsNavigation.FrontEnd();yield return null;yield return null;Check(FindAnyObjectByType<SportsFrontEnd>()!=null&&FindObjectsByType<AudioListener>(FindObjectsInactive.Exclude).Length==1,"collection transition cleans up all boats, trucks, cameras and weather");report.AppendLine("CHECKS="+checks+" ERRORS="+errors+" · native NWH/PhysX and Unity Splines; no human or controller hardware playtest.");File.WriteAllText(folder+"/result.txt",report.ToString());Application.logMessageReceived-=Error;Time.timeScale=1;
